/*
 * A084580  Let y = m/GK(k), where m and k vary over the positive integers and
 *          GK(k)=log(1+1/(k*(k+2)))/log(2) is the Gauss-Kuzmin distribution
 *          of k. Sort the y values by size and number them consecutively by
 *          n. This sequence gives the values of k in order by n.
 * https://oeis.org/A084580
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   A084580 is generated by greedily sampling the Gauss–Kuzmin
 *            distribution GK(k) = log(1+1/(k*(k+2)))/log(2). The sequence is
 *            constructed iteratively: at each step pick the integer k that
 *            minimises ((count(k)+1)/GK(k)), ties broken by the smaller k.
 *            The function returns the nth term
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   gauss_kuzmin
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <math.h>
#include "../utils/gauss_kuzmin.h"

/* Cache of already computed a(n) values */
static seq_t *cache   = NULL;   /* indices stored as 0‑based array */
static size_t cache_len = 0;    /* number of values stored */
static size_t cache_cap = 0;    /* allocated capacity */

/* Count of each integer k that has appeared so far (indexed from 1) */
static uint32_t *cnt = NULL;
static double   *p   = NULL;
static size_t k_cap  = 0;

/* Ensure that k arrays have capacity at least min_cap. */
static void ensure_k_capacity(idx_t min_cap)
{
    if (k_cap >= (size_t)min_cap) return;
    size_t new_cap = k_cap == 0 ? 1 : k_cap;
    while (new_cap < (size_t)min_cap) new_cap <<= 1;

    uint32_t *new_cnt = (uint32_t *)realloc(cnt, (new_cap + 1) * sizeof(uint32_t));
    double   *new_p   = (double   *)realloc(p,   (new_cap + 1) * sizeof(double));
    if (!new_cnt || !new_p) return;   /* allocation failure – should not happen */

    for (size_t i = k_cap + 1; i <= new_cap; ++i) {
        new_cnt[i] = 0;
        new_p[i]   = 0.0;
    }
    cnt = new_cnt;
    p   = new_p;
    k_cap = new_cap;
}

/* Ensure that the cache can store at least n terms. */
static void ensure_cache(idx_t n)
{
    if (cache_len >= (size_t)n) return;
    size_t new_cap = cache_cap == 0 ? 1 : cache_cap;
    while (new_cap < (size_t)n) new_cap <<= 1;

    seq_t *new_cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!new_cache) return;   /* allocation failure – should not happen */

    cache   = new_cache;
    cache_cap = new_cap;
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* undefined for n=0, return 0 for safety */

    ensure_cache(n);
    ensure_k_capacity(n);   /* we will never need k > n for n terms */

    /* Generate terms until the nth is available */
    while (cache_len < (size_t)n) {
        /* Find k that minimises (cnt[k] + 1) / GK(k) */
        uint32_t best_k = 1;
        double best_r = (cnt[1] + 1.0) / (p[1] == 0.0 ? gauss_kuzmin(1) : p[1]);

        for (uint32_t k = 2; k <= (uint32_t)n; ++k) {
            if (p[k] == 0.0) p[k] = gauss_kuzmin(k);
            double r = (cnt[k] + 1.0) / p[k];
            if (r < best_r) {
                best_r = r;
                best_k = k;
            }
        }

        cache[cache_len++] = (seq_t)best_k;
        cnt[best_k]++;      /* increment count for the chosen k */
    }

    return cache[n - 1];
}
